internal final class GUPRetailAttributeHelper
{
    public const str AttributeDefinitionRecIdKey = 'AttributeRecId';
    public const str AttributeDefinitionNameKey = 'AttributeName';
    public const str AttributeDefinitionTypeNameKey = 'AttributeTypeName';
    public const str AttributeDefinitionDataTypeKey = 'DataType';
    public const str AttributeDefinitionIsEnumerationKey = 'IsEnumeration';
    public const str AttributeDefinitionMetadataKey = 'Metadata';
    public const str AttributeDefinitionDefaultValueKey = 'DefaultValues';
    public const str AttributeDefinitionLowerBoundKey = 'LowerBound';
    public const str AttributeDefinitionUpperBoundKey = 'UpperBound';

}

