private static container createTestAttributeGroupAttribute(EcoResAttribute attribute, EcoResAttribute attribute2 = null)
{
    EcoResAttributeGroupAttribute attributeGroupAttribute, attributeGroupAttribute2;
    EcoResAttributeGroup attributeGroup;
    EcoResTextValue defaultValue, defaultValue2;

    attributeGroup.Name = guid2str(newGuid());
    attributeGroup.insert();

    defaultValue.TextValue = guid2str(newGuid());
    defaultValue.insert();

    attributeGroupAttribute.AttributeGroup = attributeGroup.RecId;
    attributeGroupAttribute.Attribute = attribute.RecId;
    attributeGroupAttribute.DefaultValue = defaultValue.RecId;
    attributeGroupAttribute.insert();

    if (attribute2)
    {
        defaultValue2.TextValue = guid2str(newGuid());
        defaultValue2.insert();

        attributeGroupAttribute2.AttributeGroup = attributeGroup.RecId;
        attributeGroupAttribute2.Attribute = attribute2.RecId;
        attributeGroupAttribute2.DefaultValue = defaultValue2.RecId;
        attributeGroupAttribute2.insert();
    }

    return [defaultValue, attributeGroup, attributeGroupAttribute, attributeGroupAttribute2];
}

public static EcoResBooleanValue createBooleanValue(boolean _booleanValue)
{
    EcoResBooleanValue erbv;

    erbv.initValue();
    erbv.BooleanValue = _booleanValue ? 1 : 0;
    erbv.insert();

    return erbv;
}

public static EcoResTextValue createTextValue(str _textValue)
{
