/// <summary>
/// Creates an attribute group.
/// </summary>
/// <param name = "_attributeGroupName">The attribute group name.</param>
/// <param name = "_attributeNamesRecId">List of attribute definition record identifier to be part of the attribute group.</param>
/// <returns>Table that contains attribute group details.</returns>
public static EcoResAttributeGroup createAttributeGroup(str _attributeGroupName, Set _attributeNamesRecId = new Set(Types::Int64))
{
    EcoResAttributeGroup erag;
    EcoResAttributeGroupAttribute eraga;

    erag.initValue();
    erag.Name  = _attributeGroupName;
    erag.insert();

    SetEnumerator enumerator = _attributeNamesRecId.getEnumerator();

    while (enumerator.moveNext())
    {
        eraga.initValue();
        eraga.Attribute = enumerator.current();
        eraga.AttributeGroup = erag.RecId;
        eraga.insert();
    }

    return erag;
}

/// <summary>
/// Creates a default value of attribute definition.
/// </summary>
/// <param name = "_attributeRecId">Attribute definition record identifier.</param>
/// <param name = "_dataType">Attribute data type.</param>
/// <param name = "_value">The value of an attribute.</param>
/// <returns>Table <c>EcoResAttributeDefaultValue</c> that contains record of default value.</returns>
public static EcoResAttributeDefaultValue createDefaultValue(RefRecId _attributeRecId, AttributeDataType _dataType, anytype _value)
{
    EcoResAttributeDefaultValue eradv;
    RefRecId valueRecId;

    switch (_dataType)
    {
        case AttributeDataType::Text:
            valueRecId = GUPRetailAttributeHelper::createTextValue(_value).RecId;
            break;
        case AttributeDataType::TrueFalse:
            valueRecId = GUPRetailAttributeHelper::createBooleanValue(_value).RecId;
            break;
        case AttributeDataType::Integer:
            valueRecId = GUPRetailAttributeHelper::createIntValue(_value).RecId;
            break;
        case AttributeDataType::Decimal:
            valueRecId = GUPRetailAttributeHelper::createDecimalValue(_value).RecId;
            break;
        case AttributeDataType::DateTime:
            valueRecId = GUPRetailAttributeHelper::createDateTimeValue(_value).RecId;
            break;
    }

    eradv.initValue();
    eradv.Attribute = _attributeRecId;
    eradv.Value = valueRecId;
    eradv.insert();

    return eradv;
}

/// <summary>
/// Creates attribute definition.
/// </summary>
/// <param name = "_properties">Dictionary that contains data needed for creating attribute definition.</param>
/// <returns>Table that contains attribute definition.</returns>
public static EcoResAttribute createAttributeDefinition(Map _properties)
{
    EcoResAttributeType erat;
    EcoResAttribute era;
    RetailAttributeMetadata ram;

    // Insert to table EcoResAttributeType.
    erat.initValue();

    if (_properties.exists(AttributeDefinitionTypeNameKey))
    {
        erat.Name = _properties.lookup(AttributeDefinitionTypeNameKey);
    }
    else
    {
        // Set default name of attribute type: [AttributeDefinitionName] + 'Type'
        erat.Name = _properties.lookup(AttributeDefinitionNameKey) + 'Type';
    }

    erat.DataType = _properties.lookup(AttributeDefinitionDataTypeKey);

    if (_properties.exists(AttributeDefinitionIsEnumerationKey))
    {
        erat.IsEnumeration = _properties.lookup(AttributeDefinitionIsEnumerationKey);
    }

    erat.insert();

    // Insert to table EcoResAttribute.
    era.initValue();
    era.AttributeType = erat.RecId;
    era.Name = _properties.lookup(AttributeDefinitionNameKey);
    era.insert();

    _properties.insert(AttributeDefinitionRecIdKey, era.RecId);

    // Update attribute metadata
    if (_properties.exists(AttributeDefinitionMetadataKey))
    {
        select forupdate ram
        where ram.Attribute == era.RecId;

        ram.Metadata = _properties.lookup(AttributeDefinitionMetadataKey);
        ram.MetadataVersion = 2;
        ram.update();
    }

    // Create default value
    if (_properties.exists(AttributeDefinitionDefaultValueKey))
    {
        GUPRetailAttributeHelper::createDefaultValue(era.RecId, erat.DataType, _properties.lookup(AttributeDefinitionDefaultValueKey));
    }

    // Create boundary value
    if (_properties.exists(AttributeDefinitionLowerBoundKey))
    {
        GUPRetailAttributeHelper::createAttributeBoundaries(
            _properties.lookup(AttributeDefinitionLowerBoundKey),
            _properties.lookup(AttributeDefinitionUpperBoundKey),
            erat.RecId,
            erat.DataType);
    }

    return era;
}

private static void createAttributeBoundaries(anytype _lowerBoundary, anytype _upperBoundary, RefRecId _attributeTypeRecId, AttributeDataType _dataType)
{
    EcoResDateTimeValue ecoResDateTimeValue;
    EcoResIntValue eroResIntValue;
    EcoResFloatValue ecoResFloatValue;
    EcoResBoundedAttributeTypeValue ecoResBoundedAttributeTypeValue;
    RefRecId lowerBoundRecId, upperBoundRecId;

    switch (_dataType)
    {
        case AttributeDataType::DateTime:
            ecoResDateTimeValue = GUPRetailAttributeHelper::createDateTimeValue(_lowerBoundary);
            lowerBoundRecId = ecoResDateTimeValue.RecId;
            ecoResDateTimeValue = GUPRetailAttributeHelper::createDateTimeValue(_upperBoundary);
            upperBoundRecId = ecoResDateTimeValue.RecId;
            break;
        case AttributeDataType::Decimal:
            ecoResFloatValue = GUPRetailAttributeHelper::createDecimalValue(_lowerBoundary);
            lowerBoundRecId = ecoResFloatValue.RecId;
            ecoResFloatValue = GUPRetailAttributeHelper::createDecimalValue(_upperBoundary);
            upperBoundRecId = ecoResFloatValue.RecId;
            break;
        case AttributeDataType::Integer:
            eroResIntValue = GUPRetailAttributeHelper::createIntValue(_lowerBoundary);
            lowerBoundRecId = eroResIntValue.RecId;
            eroResIntValue = GUPRetailAttributeHelper::createIntValue(_upperBoundary);
            upperBoundRecId = eroResIntValue.RecId;
            break;
    }

    ecoResBoundedAttributeTypeValue.initValue();
    ecoResBoundedAttributeTypeValue.AttributeType = _attributeTypeRecId;
    ecoResBoundedAttributeTypeValue.LowerBound = lowerBoundRecId;
    ecoResBoundedAttributeTypeValue.UpperBound = upperBoundRecId;
    ecoResBoundedAttributeTypeValue.insert();
}
